/**
 * Organization rows plus slug uniqueness lookups.
 *
 * Must call (do not reimplement): archivePatch, uniqueSlug
 */
import { and, eq, isNull, like } from "drizzle-orm";
import { newId } from "@/lib/id";
import { uniqueSlug } from "@/lib/slug";
import { archivePatch } from "@/lib/soft-delete";
import { getDb, members, organizations } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { toOrganization } from "./_mappers";
import type {
  CreateOrganizationInput,
  UpdateOrganizationInput,
} from "@/schemas/organization";
import type { OrgId, UserId } from "@/types/common";
import type { Organization } from "@/types/organization";

export async function findOrgById(orgId: OrgId): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(eq(organizations.id, orgId))
    .get();
  return row ? toOrganization(row) : null;
}

export async function findOrgBySlug(slug: string): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(and(eq(organizations.slug, slug), isNull(organizations.archivedAt)))
    .get();
  return row ? toOrganization(row) : null;
}

/** Every org the user still holds a live membership in. */
export async function listOrgsForUser(
  userId: UserId,
): Promise<readonly Organization[]> {
  const rows = getDb()
    .select({ org: organizations })
    .from(members)
    .innerJoin(organizations, eq(organizations.id, members.orgId))
    .where(
      and(
        eq(members.userId, userId),
        isNull(members.archivedAt),
        isNull(organizations.archivedAt),
      ),
    )
    .all();

  return rows.map((row) => toOrganization(row.org));
}

/**
 * Creates the org row. The slug is de-duplicated here rather than in the
 * service so a race on the unique index still resolves to a usable slug.
 */
export async function insertOrg(
  input: CreateOrganizationInput,
  ownerId: UserId,
): Promise<Organization> {
  const taken = await listTakenOrgSlugs(input.slug);
  const slug = uniqueSlug(input.slug, taken);
  const stamp = toIsoTimestamp(new Date());

  const row = getDb()
    .insert(organizations)
    .values({
      id: newId(),
      name: input.name,
      slug,
      ownerId,
      plan: input.plan,
      logoUrl: null,
      trialEndsAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toOrganization(row);
}

export async function updateOrg(
  orgId: OrgId,
  patch: UpdateOrganizationInput,
): Promise<Organization> {
  const current = await findOrgById(orgId);
  if (!current) throw new Error(`Organization ${orgId} not found`);

  // Overrides are a set, not a list to replace: merge so that a patch naming
  // one flag never silently drops the ones switched on before it.
  const settings = {
    ...current.settings,
    ...(patch.settings ?? {}),
    enabledFlagOverrides: [
      ...new Set([
        ...current.settings.enabledFlagOverrides,
        ...(patch.settings?.enabledFlagOverrides ?? []),
      ]),
    ],
  };

  const row = getDb()
    .update(organizations)
    .set({
      ...(patch.name === undefined ? {} : { name: patch.name }),
      ...(patch.logoUrl === undefined ? {} : { logoUrl: patch.logoUrl }),
      defaultIssueStatus: settings.defaultIssueStatus,
      allowPublicProjects: settings.allowPublicProjects,
      requireTwoFactor: settings.requireTwoFactor,
      digestHourUtc: settings.digestHourUtc,
      enabledFlagOverrides: JSON.stringify(settings.enabledFlagOverrides),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  return toOrganization(row);
}

export async function archiveOrg(orgId: OrgId): Promise<Organization> {
  const row = getDb()
    .update(organizations)
    .set(archivePatch())
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Organization ${orgId} not found`);
  return toOrganization(row);
}

/** Feeds `uniqueSlug()`; matching on the prefix keeps the scan small. */
export async function listTakenOrgSlugs(
  prefix: string,
): Promise<readonly string[]> {
  const rows = getDb()
    .select({ slug: organizations.slug })
    .from(organizations)
    .where(like(organizations.slug, `${prefix}%`))
    .all();
  return rows.map((row) => row.slug);
}

import type {
  FeatureFlagDefinition,
  FeatureFlagKey,
} from "@/types/feature-flag";

/**
 * Declarative registry of every feature flag. `isEnabled()` in
 * `src/lib/feature-flags.ts` is the only reader — UI and server code go
 * through that function, never through this table directly.
 */
export const FEATURE_FLAG_DEFINITIONS: Readonly<
  Record<FeatureFlagKey, FeatureFlagDefinition>
> = {
  kanban_board: {
    key: "kanban_board",
    label: "Kanban board",
    description: "Drag-and-drop board view for a project's issues.",
    strategy: { kind: "plan", minPlan: "starter" },
    overridable: true,
  },
  ai_issue_summary: {
    key: "ai_issue_summary",
    label: "AI issue summary",
    description: "Generates a short summary of a long issue thread.",
    strategy: { kind: "percentage", percent: 25 },
    overridable: true,
  },
  command_palette: {
    key: "command_palette",
    label: "Command palette",
    description: "Ctrl+K quick navigation and actions.",
    strategy: { kind: "on" },
    overridable: false,
  },
  activity_feed: {
    key: "activity_feed",
    label: "Activity feed",
    description: "Organization-wide audit trail view.",
    strategy: { kind: "plan", minPlan: "growth" },
    overridable: true,
  },
  public_projects: {
    key: "public_projects",
    label: "Public projects",
    description: "Share a read-only project page outside the organization.",
    strategy: { kind: "plan", minPlan: "enterprise" },
    overridable: true,
  },
  webhooks: {
    key: "webhooks",
    label: "Outgoing webhooks",
    description: "Deliver domain events to an external HTTP endpoint.",
    strategy: { kind: "plan", minPlan: "growth" },
    overridable: false,
  },
  csv_export: {
    key: "csv_export",
    label: "CSV export",
    description: "Export issues and the audit log as CSV.",
    strategy: { kind: "plan", minPlan: "starter" },
    overridable: true,
  },
  digest_email: {
    key: "digest_email",
    label: "Daily digest email",
    description: "Batches notifications into one daily email.",
    strategy: { kind: "plan", minPlan: "growth" },
    overridable: true,
  },
  issue_templates: {
    key: "issue_templates",
    label: "Issue templates",
    description: "Prefilled issue bodies per project.",
    strategy: { kind: "role", minRole: "admin" },
    overridable: true,
  },
  advanced_search: {
    key: "advanced_search",
    label: "Advanced search",
    description: "Field-scoped query syntax across issues and comments.",
    strategy: { kind: "plan", minPlan: "enterprise" },
    overridable: true,
  },
};

export const FEATURE_FLAG_KEYS = Object.keys(
  FEATURE_FLAG_DEFINITIONS,
) as readonly FeatureFlagKey[];

export function getFlagDefinition(key: FeatureFlagKey): FeatureFlagDefinition {
  return FEATURE_FLAG_DEFINITIONS[key];
}

export function isFeatureFlagKey(value: string): value is FeatureFlagKey {
  return Object.prototype.hasOwnProperty.call(FEATURE_FLAG_DEFINITIONS, value);
}

