import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { isEnabled } from "@/lib/feature-flags";
import { FlagNotOverridableError } from "@/lib/feature-flags";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as flagService from "@/server/services/feature-flag-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { FlagContext } from "@/types/feature-flag";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

function ctxFor(org: { id: string; plan: FlagContext["plan"]; settings: { enabledFlagOverrides: readonly string[] } }): FlagContext {
  return {
    orgId: org.id as FlagContext["orgId"],
    userId: null,
    plan: org.plan,
    role: "owner",
    overrides: org.settings.enabledFlagOverrides,
  };
}

describe("tmp feature flag overrides", () => {
  it("on -> off -> on works on a free workspace and removes only that override", async () => {
    const tenant = await createTenant("tmp-toggle-free", "free");
    const orgId = tenant.org.id;
    const owner = tenant.actors.owner;

    await flagService.toggleFlag(owner, { orgId, flag: "kanban_board", enabled: true });
    await flagService.toggleFlag(owner, { orgId, flag: "csv_export", enabled: true });
    let org = (await orgRepo.findOrgById(orgId))!;
    expect(org.settings.enabledFlagOverrides.sort()).toEqual(["csv_export", "kanban_board"]);
    expect(isEnabled("kanban_board", ctxFor(org))).toBe(true);

    await flagService.toggleFlag(owner, { orgId, flag: "kanban_board", enabled: false });
    org = (await orgRepo.findOrgById(orgId))!;
    expect(org.settings.enabledFlagOverrides).toEqual(["csv_export"]);
    expect(isEnabled("kanban_board", ctxFor(org))).toBe(false);
    expect(isEnabled("csv_export", ctxFor(org))).toBe(true);

    await flagService.toggleFlag(owner, { orgId, flag: "kanban_board", enabled: true });
    org = (await orgRepo.findOrgById(orgId))!;
    expect(org.settings.enabledFlagOverrides.sort()).toEqual(["csv_export", "kanban_board"]);
    expect(isEnabled("kanban_board", ctxFor(org))).toBe(true);
  });

  it("rejects switching on a plan-only, non-overridable flag and stores nothing", async () => {
    const tenant = await createTenant("tmp-webhooks-free", "free");
    const orgId = tenant.org.id;

    await expect(
      flagService.toggleFlag(tenant.actors.owner, { orgId, flag: "webhooks", enabled: true }),
    ).rejects.toBeInstanceOf(FlagNotOverridableError);

    const org = (await orgRepo.findOrgById(orgId))!;
    expect(org.settings.enabledFlagOverrides).toEqual([]);
    expect(isEnabled("webhooks", ctxFor(org))).toBe(false);
  });

  it("ignores a stored override on a non-overridable flag", async () => {
    const tenant = await createTenant("tmp-stored-webhooks", "free");
    const orgId = tenant.org.id;

    await orgRepo.setFlagOverrides(orgId, ["webhooks", "command_palette"]);
    const org = (await orgRepo.findOrgById(orgId))!;
    expect(isEnabled("webhooks", ctxFor(org))).toBe(false);
    // command_palette is `on` by strategy, so the stored override is moot but harmless.
    expect(isEnabled("command_palette", ctxFor(org))).toBe(true);
  });

  it("keeps stored overrides when a settings save runs without them", async () => {
    const tenant = await createTenant("tmp-settings-keep", "free");
    const orgId = tenant.org.id;

    await flagService.toggleFlag(tenant.actors.owner, { orgId, flag: "kanban_board", enabled: true });
    await orgRepo.updateOrg(orgId, {
      orgId,
      settings: { digestHourUtc: 9, enabledFlagOverrides: [] },
    });
    const org = (await orgRepo.findOrgById(orgId))!;
    expect(org.settings.enabledFlagOverrides).toEqual(["kanban_board"]);
  });
});

